.ds-text { font-family: "Manrope Variable", sans-serif; cursor:pointer; }.ds-text {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 0;
  background: none;
  padding: 5px 0;
  color: #bbcdb0;
  font-size: 12px;
  text-align: left;
}
.ds-text:hover {
  color: var(--green);
}
.ds-text:focus-visible { outline: 2px solid var(--green, #b1e5a3); outline-offset: 4px; }

.ds-nav { font-family:"Manrope Variable", sans-serif; } .ds-nav button { cursor:pointer; }.ds-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.ds-nav > button {
  display: flex;
  align-items: center;
  gap: 12px;
  background: none;
  border: none;
  text-align: left;
  padding: 12px 14px;
  border-radius: 8px;
  color: #acb8a8;
  font-size: 12px;
  font-weight: 550;
  min-height: 42px;
}
.ds-nav > button:hover {
  color: #f1f7ed;
  background: #222a20;
}
.ds-nav > button.ds-selected {
  color: var(--green);
  background: #263422;
}
.ds-nav button:focus-visible { outline: 2px solid var(--green, #b1e5a3); outline-offset: 4px; }

.ds-tag { font-family:"Manrope Variable", sans-serif; }.ds-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  line-height: 1.4;
  white-space: nowrap;
  border: 1px solid #46513f;
  background: #242c21;
  color: #c0cbb9;
  padding: 4px 7px;
  border-radius: 5px;
  font-weight: 500;
}
.ds-tag.ds-good {
  background: #243d24;
  color: #c3ecb8;
  border-color: #3b6137;
}
.ds-tag.ds-warn {
  background: #493321;
  color: #f4cf9d;
  border-color: #6b4f34;
}

.ds-panel { color:#e6e9e4; font:14px "Manrope Variable", sans-serif; } .ds-title { margin:0; font-size:15px; font-weight:600; } .ds-copy { margin:12px 0 0; color:var(--muted, #a2afa1); line-height:1.75; }.ds-panel {
  border: 1px solid #3b4a31;
  border-radius: var(--radius);
  background: #1a2315;
  padding: 25px;
}

.ds-message { width:100%; color:#e6e9e4; font-family:"Manrope Variable", sans-serif; line-height:1.65; } .ds-message::placeholder { color:#9aa697; }.ds-composer {
  border: 1px solid #48553d;
  background: #1d2419;
  border-radius: var(--radius);
  padding: 16px 15px 11px;
}
.ds-composer textarea {
  border: none;
  background: none;
  padding: 0 4px;
  min-height: 48px;
  max-height: 150px;
  resize: none;
  font-size: 12px;
  box-shadow: none;
}
.ds-composer textarea:focus {
  outline: none;
}
.ds-composer:focus-within {
  border-color: #8fab76;
}
